def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 1}
    lines = set()
    for r in range(h):
        if (r, 0) in points and (r, w - 1) in points:
            lines.update((r, c) for c in range(w))
    for c in range(w):
        if (0, c) in points and (h - 1, c) in points:
            lines.update((r, c) for r in range(h))
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 2 and (r, c) not in seen:
                stack = [(r, c)]
                seen.add((r, c))
                comp = []
                hit = False
                while stack:
                    y, x = stack.pop()
                    comp.append((y, x))
                    if (y, x) in lines: hit = True
                    for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        yy, xx = y+dy, x+dx
                        if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 2 and (yy,xx) not in seen:
                            seen.add((yy,xx)); stack.append((yy,xx))
                if hit:
                    for y, x in comp: out[y][x] = 1
    for r, c in lines: out[r][c] = 1
    return out
